import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { BG, Flood, INE, KR_FPS, OUT, RED, Slash, WHITE, themeVars } from "./base";
import { G1, L1b, P1 } from "./v2A";
import { C1, H1 } from "./v2B";
import { F1, R1 } from "./v2C";
import { GameLayer, inGame } from "./v3Jogo";
import { SiteLayer } from "./v6Site";

// RIVAL motion 2 (VALORANT), versão 2: pedido do dono — "mais inversão de cor do fundo". Mesmas cenas e voz do
// KaioRivalxV2; o tema (variáveis de cor da base) vira claro/escuro no tempo da fala: fundo, painéis, texto e logo
// invertem, vermelho e dourado ficam iguais. Cenas claras inteiras + viradas rápidas nas batidas.
// v3: gameplay de VALORANT em tela cheia por baixo das cenas nos trechos de impacto (v3Jogo.tsx), sempre no tema escuro.

// v6: telas reais do site em quatro trechos (v6Site.tsx); o resto é igual à v3/v5.
export const KR6_FRAMES = Math.ceil(59.4 * KR_FPS);

// trechos claros [início, fim]
const LIGHT: [number, number][] = [
  [0.68, 1.04], // "joga"
  [2.02, 2.44], // "então presta"
  [3.81, 4.5], // "vitórias"
  [10.05, 14.85], // a plataforma
  [16.84, 17.3], // "contra"
  [20.59, 22.3], // vitória
  [26.85, 34.45], // campeonatos
  [38.56, 38.7],
  [40.18, 40.32],
  [40.95, 41.09],
  [41.87, 42.01],
  [44.12, 45.0], // primeiro lugar
  [47.45, 49.9], // "seu lugar é na Rival"
  [50.08, 50.67], // campeonatos
  [52.84, 55.45], // logo e "sua próxima partida pode valer muito mais"
];
const light = (t: number) => !inGame(t) && LIGHT.some(([a, b]) => t >= a && t < b);

type Tr = "slash" | "flood" | "zoom" | "push" | "pushUp" | "none";
const SCENES: { C: React.FC<{ t: number }>; at: number; tin: Tr }[] = [
  { C: G1, at: 0, tin: "none" },
  { C: L1b, at: 6.95, tin: "slash" },
  { C: P1, at: 10.05, tin: "zoom" },
  { C: H1, at: 14.85, tin: "flood" },
  { C: C1, at: 26.85, tin: "push" },
  { C: R1, at: 34.45, tin: "pushUp" },
  { C: F1, at: 45.65, tin: "slash" },
];
const enterOf = (tr: Tr, u: number): React.CSSProperties => {
  const e = OUT(Math.min(1, Math.max(0, u)));
  if (e >= 0.999) return {};
  if (tr === "zoom") return { transform: `scale(${(0.82 + 0.18 * e).toFixed(4)})`, filter: `blur(${((1 - e) * 14).toFixed(1)}px)`, opacity: Math.min(1, e * 2.5) };
  if (tr === "push") return { transform: `translateX(${((1 - e) * 520).toFixed(1)}px)`, filter: `blur(${((1 - e) * 10).toFixed(1)}px)`, opacity: Math.min(1, e * 2.5) };
  if (tr === "pushUp") return { transform: `translateY(${((1 - e) * 700).toFixed(1)}px)`, filter: `blur(${((1 - e) * 10).toFixed(1)}px)`, opacity: Math.min(1, e * 2.5) };
  return {};
};
const exitOf = (tr: Tr, u: number): React.CSSProperties => {
  const e = INE(Math.min(1, Math.max(0, u)));
  if (e <= 0.001) return {};
  if (tr === "zoom") return { transform: `scale(${(1 + 0.3 * e).toFixed(4)})`, filter: `blur(${(e * 16).toFixed(1)}px)`, opacity: 1 - e };
  if (tr === "push") return { transform: `translateX(${(-e * 520).toFixed(1)}px)`, filter: `blur(${(e * 10).toFixed(1)}px)`, opacity: 1 - e };
  if (tr === "pushUp") return { transform: `translateY(${(-e * 700).toFixed(1)}px)`, filter: `blur(${(e * 10).toFixed(1)}px)`, opacity: 1 - e };
  return {};
};
export const KaioRivalxV6: React.FC = () => {
  const t = useCurrentFrame() / KR_FPS;
  const inv = light(t);
  return (
    <AbsoluteFill style={{ ...themeVars(inv), background: BG }}>
      <GameLayer t={t} />
      {SCENES.map((s, i) => {
        const nx = SCENES[i + 1];
        const end = nx ? nx.at : 1e9;
        if (t < s.at || t >= end) return null;
        const st: React.CSSProperties = { ...enterOf(s.tin, (t - s.at) / 0.42), ...(nx ? exitOf(nx.tin, (t - (end - 0.25)) / 0.25) : {}) };
        return (
          <AbsoluteFill key={i} style={{ overflow: "hidden", ...st }}>
            <s.C t={t} />
          </AbsoluteFill>
        );
      })}
      <SiteLayer t={t} />
      <Slash t={t} at={6.95} c={RED} />
      <Slash t={t} at={45.65} c={WHITE} />
      <Flood t={t} at={14.85} x={540} y={1170} c={WHITE} />
    </AbsoluteFill>
  );
};

import { loadFont as loadSaira } from "@remotion/google-fonts/SairaSemiCondensed";
import { loadFont as loadChakra } from "@remotion/google-fonts/ChakraPetch";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile } from "remotion";

// RIVAL (RivalX) — base do motion 1: cores do site do cliente, fontes, texto com máscara, ícones, câmera, transições.

export const SAIRA = loadSaira("normal", { weights: ["700", "800", "900"], subsets: ["latin", "latin-ext"] }).fontFamily;
export const CHAKRA = loadChakra("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] }).fontFamily;

export const KR_FPS = 30;
// cores neutras vêm de variáveis: o fundo pode virar claro (motion VALORANT v2) sem mexer no vermelho e no dourado
export const BG = "var(--bg)";
export const PANEL = "var(--panel)";
export const PANEL2 = "var(--panel2)";
export const EDGE = "var(--edge)";
// branco fixo para texto sobre vermelho/dourado; filtro que escurece o logo branco no tema claro
export const INK = "#F4F4F5";
export const LOGO = "var(--logo)";
export const themeVars = (light: boolean) =>
  (light
    ? { "--bg": "#F4F4F5", "--panel": "#FFFFFF", "--panel2": "#ECECF0", "--edge": "#D5D5DC", "--fg": "#0B0B0E", "--muted": "#5E636C", "--logo": "invert(1)", "--white-logo": "0", "--black-logo": "1", "--gold": "#B8902A" }
    : { "--bg": "#0B0B0E", "--panel": "#15151A", "--panel2": "#1C1C22", "--edge": "#2A2A32", "--fg": "#F4F4F5", "--muted": "#9A9FA8", "--logo": "none", "--white-logo": "1", "--black-logo": "0", "--gold": "#DCB859" }) as React.CSSProperties;
// logo que troca de branco para preto com o tema (duas imagens empilhadas)
export const ThemedLogo: React.FC<{ name: "logo-rivalx" | "logo-rvl"; width: number; height?: number }> = ({ name, width, height }) => (
  <div style={{ position: "relative", width, height }}>
    <Img src={asset(`${name}.png`)} style={{ width, height, display: "block", opacity: "var(--white-logo)" as unknown as number }} />
    <Img src={asset(`${name}-preto.png`)} style={{ position: "absolute", left: 0, top: 0, width, height, display: "block", opacity: "var(--black-logo)" as unknown as number }} />
  </div>
);
export const RED = "#FF2A3F";
export const DRED = "#991926";
export const TEAL = "#009982";
export const GOLD = "var(--gold)";
export const GRAY = "var(--muted)";
export const WHITE = "var(--fg)";
export const asset = (f: string) => staticFile(`kaio-rivalx/${f}`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
export const OUT = Easing.bezier(0.16, 1, 0.3, 1);
export const IO = Easing.bezier(0.65, 0, 0.35, 1);
export const INE = Easing.bezier(0.5, 0, 0.75, 0);
export const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
export const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IO });
export const ein = (t: number, a: number, d = 0.3) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: INE });
export const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
export const mix = (a: number, b: number, p: number) => a + (b - a) * p;
// mola com pouco overshoot (~4%)
export const pop = (t: number, a: number, d = 0.5) => {
  const x = (t - a) / d;
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  return 1 - Math.exp(-5 * x) * Math.cos(4 * x);
};
export const bump = (t: number, at: number, amt = 0.06, d = 0.35) => (t >= at && t < at + d ? amt * Math.sin(((t - at) / d) * Math.PI) : 0);
const fit = (s: string, cap: number, w = 840, f = 0.6) => Math.min(cap, Math.floor(w / (s.length * f)));

// ───────── texto: cada palavra sobe de trás de uma linha (máscara) e fica parada ─────────
export type Wd = [string, number, string?];
export const Line: React.FC<{ t: number; words: Wd[]; size: number; out?: number; color?: string }> = ({ t, words, size, out = 1e9, color = WHITE }) => {
  const o = ein(t, out, 0.28);
  return (
    <div style={{ display: "flex", justifyContent: "center", gap: size * 0.26, whiteSpace: "nowrap", fontFamily: SAIRA, fontWeight: 900, fontSize: size, lineHeight: 1.04, letterSpacing: "-0.005em", textTransform: "uppercase" }}>
      {words.map(([w, at, c], i) => {
        const e = k(t, at - 0.06, 0.42);
        const y = t >= out ? -o * 108 : (1 - e) * 108;
        return (
          <span key={i} style={{ display: "inline-block", overflow: "hidden", padding: `${size * 0.06}px 0.04em ${size * 0.1}px`, margin: `${-size * 0.06}px -0.04em ${-size * 0.1}px` }}>
            <span style={{ display: "inline-block", color: c ?? color, transform: `translateY(${y.toFixed(1)}%)`, opacity: e > 0.001 && o < 0.999 ? 1 : 0 }}>{w}</span>
          </span>
        );
      })}
    </div>
  );
};
// bloco de título fixo no alto da coluna central
export const Title: React.FC<{ t: number; top?: number; from: number; to: number; lines: { words: Wd[]; cap?: number; color?: string }[] }> = ({ t, top = 300, from, to, lines }) => {
  if (t < from - 0.1 || t > to + 0.35) return null;
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap: 6 }}>
      {lines.map((l, i) => (
        <Line key={i} t={t} words={l.words.map(([w, at, c]) => [w, Math.max(at, from + 0.24), c] as Wd)} size={fit(l.words.map((w) => w[0]).join(" "), l.cap ?? 120)} out={to - 0.02 + i * 0.04} color={l.color} />
      ))}
    </div>
  );
};
export const Label: React.FC<{ children: React.ReactNode; size?: number; color?: string }> = ({ children, size = 34, color = GRAY }) => (
  <div style={{ fontFamily: CHAKRA, fontWeight: 700, fontSize: size, letterSpacing: "0.14em", color, textTransform: "uppercase", whiteSpace: "nowrap" }}>{children}</div>
);

// câmera da camada de objetos (o texto fica parado por cima)
export const Cam: React.FC<{ t: number; a: number; b: number; z?: [number, number]; x?: [number, number]; y?: [number, number]; r?: [number, number]; origin?: string; children: React.ReactNode }> = ({ t, a, b, z = [1, 1], x = [0, 0], y = [0, 0], r = [0, 0], origin = "50% 55%", children }) => {
  const p = interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.bezier(0.33, 0.1, 0.4, 1) });
  return (
    <AbsoluteFill style={{ transformOrigin: origin, transform: `translate(${mix(x[0], x[1], p).toFixed(1)}px, ${mix(y[0], y[1], p).toFixed(1)}px) scale(${mix(z[0], z[1], p).toFixed(4)}) rotate(${mix(r[0], r[1], p).toFixed(2)}deg)` }}>
      {children}
    </AbsoluteFill>
  );
};
export const Box: React.FC<{ x: number; y: number; w: number; h: number; style?: React.CSSProperties; children?: React.ReactNode }> = ({ x, y, w, h, style, children }) => (
  <div style={{ position: "absolute", left: x, top: y, width: w, height: h, boxSizing: "border-box", ...style }}>{children}</div>
);
export const Bar: React.FC<{ w: number; h?: number; c?: string; style?: React.CSSProperties }> = ({ w, h = 18, c = "#2C2C35", style }) => <div style={{ width: w, height: h, borderRadius: h / 2, background: c, ...style }} />;
export const AVATAR = `radial-gradient(circle at 50% 38%, #5A5A66 0 28%, transparent 29%), radial-gradient(ellipse at 50% 100%, #5A5A66 0 46%, transparent 47%), #2A2A32`;

// ───────── ícones (traço) ─────────
export const Ico: React.FC<{ name: string; size: number; color?: string; stroke?: number; open?: number }> = ({ name, size, color = WHITE, stroke = 7, open = 0 }) => {
  const p = { fill: "none", stroke: color, strokeWidth: stroke, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  const g: Record<string, React.ReactNode> = {
    lock: (
      <>
        <rect x={20} y={46} width={60} height={44} rx={8} {...p} />
        <path d="M33 46 V32 a17 17 0 0 1 34 0 V46" {...p} transform={`translate(${(open * 20).toFixed(1)} ${(-open * 10).toFixed(1)}) rotate(${(-open * 25).toFixed(1)} 67 46)`} />
        <circle cx={50} cy={66} r={5} fill={color} />
      </>
    ),
    pct: (
      <>
        <path d="M74 22 L26 78" {...p} />
        <circle cx={32} cy={30} r={10} {...p} />
        <circle cx={68} cy={70} r={10} {...p} />
      </>
    ),
    up: <path d="M50 80 V22 M28 44 L50 22 L72 44" {...p} />,
    trophy: (
      <>
        <path d="M30 18 H70 V42 a20 20 0 0 1 -40 0 Z" {...p} />
        <path d="M30 26 H16 a12 12 0 0 0 14 22 M70 26 H84 a12 12 0 0 1 -14 22" {...p} />
        <path d="M50 62 V76 M34 86 H66 M40 76 H60" {...p} />
      </>
    ),
    users: (
      <>
        <circle cx={38} cy={36} r={13} {...p} />
        <path d="M14 80 a24 24 0 0 1 48 0" {...p} />
        <circle cx={68} cy={38} r={10} {...p} />
        <path d="M66 58 a20 20 0 0 1 22 22" {...p} />
      </>
    ),
    headset: (
      <>
        <path d="M18 58 V48 a32 32 0 0 1 64 0 V58" {...p} />
        <rect x={14} y={54} width={16} height={26} rx={6} {...p} />
        <rect x={70} y={54} width={16} height={26} rx={6} {...p} />
        <path d="M78 80 q0 10 -18 10 H52" {...p} />
      </>
    ),
    chat: (
      <>
        <path d="M18 24 H82 V66 H46 L30 80 V66 H18 Z" {...p} />
        <path d="M34 42 H66 M34 54 H56" {...p} />
      </>
    ),
    friend: (
      <>
        <circle cx={42} cy={34} r={14} {...p} />
        <path d="M16 82 a26 26 0 0 1 52 0" {...p} />
        <path d="M78 34 V58 M66 46 H90" {...p} />
      </>
    ),
    link: (
      <>
        <path d="M44 56 a14 14 0 0 0 20 0 L76 44 a14 14 0 0 0 -20 -20 L50 30" {...p} />
        <path d="M56 44 a14 14 0 0 0 -20 0 L24 56 a14 14 0 0 0 20 20 L50 70" {...p} />
      </>
    ),
    bolt: <path d="M56 12 L24 56 H48 L42 88 L76 42 H52 Z" {...p} />,
    check: <path d="M24 52 L42 70 L78 32" {...p} />,
    play: <path d="M36 26 L74 50 L36 74 Z" {...p} />,
  };
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ display: "block", overflow: "visible" }}>
      {g[name]}
    </svg>
  );
};
export const Cursor: React.FC<{ x: number; y: number; press?: number }> = ({ x, y, press = 0 }) => (
  <div style={{ position: "absolute", left: x, top: y, transform: `scale(${(1 - press * 0.12).toFixed(3)})`, transformOrigin: "0 0", zIndex: 20 }}>
    <svg width={64} height={78} viewBox="0 0 32 39" style={{ filter: "drop-shadow(0 6px 10px rgba(0,0,0,0.6))" }}>
      <path d="M2 2 L2 31 L9.5 24 L15 36.5 L20 34.3 L14.6 22 L25 22 Z" fill={WHITE} stroke="#111" strokeWidth={2} strokeLinejoin="round" />
    </svg>
  </div>
);
// caminho do cursor: lista de [tempo, x, y]
export const curPos = (t: number, path: [number, number, number][]) => {
  if (t <= path[0][0]) return [path[0][1], path[0][2]];
  for (let i = 1; i < path.length; i++) {
    if (t < path[i][0]) {
      const p = io(t, path[i - 1][0], path[i][0] - path[i - 1][0]);
      return [mix(path[i - 1][1], path[i][1], p), mix(path[i - 1][2], path[i][2], p)];
    }
  }
  const l = path[path.length - 1];
  return [l[1], l[2]];
};
export const pressAt = (t: number, clicks: number[]) => clicks.reduce((m, c) => Math.max(m, t >= c && t < c + 0.18 ? Math.sin(((t - c) / 0.18) * Math.PI) : 0), 0);
export const Ripple: React.FC<{ t: number; at: number; x: number; y: number; c?: string }> = ({ t, at, x, y, c = WHITE }) => {
  if (t < at || t > at + 0.5) return null;
  const u = (t - at) / 0.5;
  return <div style={{ position: "absolute", left: x - 50, top: y - 50, width: 100, height: 100, borderRadius: 50, border: `4px solid ${c}`, opacity: 0.7 * (1 - u), transform: `scale(${(0.3 + u * 0.9).toFixed(3)})`, zIndex: 19 }} />;
};

// ───────── transições ─────────
// lâmina diagonal (a ponta do X do logo) que corta a tela
export const Slash: React.FC<{ t: number; at: number; c?: string }> = ({ t, at, c = RED }) => {
  if (t < at - 0.3 || t > at + 0.34) return null;
  return (
    <AbsoluteFill style={{ overflow: "hidden", zIndex: 40 }}>
      {[c, BG].map((col, i) => {
        const p = interpolate(t, [at - 0.28 + i * 0.07, at + 0.22 + i * 0.07], [0, 1], { ...cl, easing: IO });
        return <div key={i} style={{ position: "absolute", left: -2300 + p * 4500, top: -400, width: 1500, height: 2800, background: col, transform: "skewX(-24deg)" }} />;
      })}
    </AbsoluteFill>
  );
};
// inundação de cor saindo de um ponto
export const Flood: React.FC<{ t: number; at: number; x: number; y: number; c?: string }> = ({ t, at, x, y, c = RED }) => {
  if (t < at - 0.3 || t > at + 0.35) return null;
  const grow = io(t, at - 0.3, 0.3);
  const go = io(t, at, 0.35);
  return <AbsoluteFill style={{ zIndex: 40, background: c, clipPath: `circle(${(grow * 2300).toFixed(0)}px at ${x}px ${y}px)`, opacity: 1 - go }} />;
};

// logo animado do cliente (RIVAL → X → RX), fundo preto somado por "screen"
const LOGO_DUR = 5.5;
export const LogoAnim: React.FC<{ t: number; at: number; until: number }> = ({ t, at, until }) => {
  const z = mix(1.0, 1.07, lin(t, at, until));
  const frozen = t >= at + LOGO_DUR - 0.05;
  return (
    <AbsoluteFill style={{ transform: `translateY(-120px) scale(${z.toFixed(4)})`, transformOrigin: "50% 50%", mixBlendMode: "screen" }}>
      {frozen ? (
        <Img src={asset("logo-rx-fim.png")} style={{ width: 1080, height: 1920, mixBlendMode: "screen" }} />
      ) : (
        <Sequence from={Math.round(at * KR_FPS)} durationInFrames={Math.round(LOGO_DUR * KR_FPS)} layout="none">
          <OffthreadVideo src={asset("logo-anim.mp4")} muted style={{ width: 1080, height: 1920, mixBlendMode: "screen" }} />
        </Sequence>
      )}
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, Img, OffthreadVideo, Sequence } from "remotion";
import { BG, Bar, Box, CHAKRA, INK, ThemedLogo, Cam, EDGE, GOLD, GRAY, Ico, KR_FPS, Label, Line, PANEL, PANEL2, RED, SAIRA, Title, WHITE, Wd, asset, bump, ein, io, k, lin, mix, pop } from "./base";

// RIVAL motion 2 (VALORANT) — gancho, logo e visão geral. Preto, branco e cinza; vermelho só no destaque, dourado no dinheiro.

// glitch curto de fatias horizontais na entrada (sem separar cores)
export const Glitch: React.FC<{ t: number; at: number; d?: number; children: React.ReactNode }> = ({ t, at, d = 0.2, children }) => {
  if (t < at || t > at + d) return <>{children}</>;
  const f = Math.floor((t - at) * 30);
  const bands = [
    [0, 30, ((f * 37) % 7) - 3],
    [30, 55, ((f * 53) % 9) * 6 - 24],
    [55, 100, ((f * 29) % 5) * -4 + 8],
  ];
  return (
    <div style={{ position: "relative" }}>
      <div style={{ visibility: "hidden" }}>{children}</div>
      {bands.map(([a, b, dx], i) => (
        <div key={i} style={{ position: "absolute", inset: 0, clipPath: `inset(${a}% 0 ${100 - b}% 0)`, transform: `translateX(${dx}px)` }}>
          {children}
        </div>
      ))}
    </div>
  );
};
// mira: quatro traços e o ponto
export const Crosshair: React.FC<{ size: number; color?: string; gap?: number; w?: number }> = ({ size, color = WHITE, gap = 0.22, w = 10 }) => {
  const h = size / 2;
  const g = size * gap;
  return (
    <svg width={size} height={size} style={{ display: "block", overflow: "visible" }}>
      <circle cx={h} cy={h} r={h - w} fill="none" stroke={color} strokeWidth={w * 0.5} opacity={0.35} />
      {[
        [h, 0, h, h - g],
        [h, h + g, h, size],
        [0, h, h - g, h],
        [h + g, h, size, h],
      ].map(([x1, y1, x2, y2], i) => (
        <line key={i} x1={x1} y1={y1} x2={x2} y2={y2} stroke={color} strokeWidth={w} strokeLinecap="round" />
      ))}
      <circle cx={h} cy={h} r={w * 0.9} fill={RED} />
    </svg>
  );
};
const Big: React.FC<{ t: number; words: Wd[]; size: number; out: number; color?: string }> = (p) => <Line {...p} />;

// ───────── cena 1: gancho ─────────
export const G1: React.FC<{ t: number }> = ({ t }) => {
  const snap = pop(t, 0, 0.55);
  const recoil = bump(t, 0.22, 0.06, 0.2) + bump(t, 0.68, 0.06, 0.2) + bump(t, 1.06, 0.1, 0.25) + bump(t, 2.02, 0.05, 0.2);
  const away = io(t, 3.6, 0.4);
  const V = 3.81, P = 4.52;
  const toPrize = io(t, P, 0.45);
  return (
    <>
      <Cam t={t} a={0} b={7} z={[1.0, 1.08]}>
        {/* mira atrás do texto grande */}
        <div style={{ position: "absolute", left: 540 - 380, top: 1000 - 380, width: 760, height: 760, opacity: (0.35 + 0.65 * k(t, 0, 0.2)) * (1 - away) * 0.4, transform: `scale(${((2.6 - 1.6 * snap) * (1 + recoil) * (1 - away * 0.4)).toFixed(3)}) rotate(${((1 - snap) * 45).toFixed(1)}deg)`, filter: snap < 0.9 ? `blur(${((1 - snap) * 10).toFixed(1)}px)` : undefined }}>
          <Crosshair size={760} color={GRAY} w={12} />
        </div>
        {/* vitória que vira premiação */}
        {t > V - 0.1 ? (
          <AbsoluteFill>
            <div style={{ position: "absolute", left: 120, width: 840, top: 880, height: 220, borderRadius: 28, background: mix(0, 1, toPrize) > 0.5 ? PANEL : RED, border: `4px solid ${toPrize > 0.5 ? GOLD : RED}`, boxSizing: "border-box", display: "flex", alignItems: "center", justifyContent: "center", gap: 30, transform: `scale(${(pop(t, V, 0.45) * (1 + bump(t, P, 0.08, 0.3))).toFixed(3)}) rotateX(${(Math.sin(toPrize * Math.PI) * 70).toFixed(1)}deg)`, boxShadow: toPrize > 0.5 ? "0 0 40px rgba(220,184,89,0.35)" : "0 0 40px rgba(255,42,63,0.4)" }}>
              {toPrize <= 0.5 ? (
                <div style={{ fontFamily: SAIRA, fontWeight: 900, fontSize: 130, color: INK, letterSpacing: "0.04em" }}>VITÓRIA</div>
              ) : (
                <>
                  <div style={{ width: 130, height: 130, borderRadius: 65, background: GOLD, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: SAIRA, fontWeight: 900, fontSize: 64, color: "#4A3A10" }}>R$</div>
                  <div style={{ fontFamily: SAIRA, fontWeight: 900, fontSize: 96, color: GOLD, letterSpacing: "0.02em" }}>PREMIAÇÃO</div>
                </>
              )}
            </div>
            {Array.from({ length: 8 }, (_, i) => {
              const at = 5.3 + i * 0.05;
              const e = pop(t, at, 0.55);
              // moedas num arco por baixo do cartão
              const a = (90 + (i - 3.5) * 19) * (Math.PI / 180);
              const R = 330 + (i % 2) * 60;
              return e > 0 ? (
                <div key={i} style={{ position: "absolute", left: 540 + Math.cos(a) * R * e - 36, top: 1000 + Math.sin(a) * R * e - 36, width: 72, height: 72, borderRadius: 36, background: GOLD, border: "6px solid #B39340", boxSizing: "border-box", transform: `scale(${e.toFixed(3)})` }} />
              ) : null;
            })}
          </AbsoluteFill>
        ) : null}
      </Cam>
      {/* texto grande no centro nos primeiros 3,6 s */}
      {t < 2.05 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 760, display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
          <Big t={t} words={[["Você", 0.18], ["joga", 0.64]]} size={170} out={1.92} />
          <Glitch t={t} at={1.06} d={0.22}>
            <Big t={t} words={[["Valorant?", 1.0]]} size={176} out={1.96} color={RED} />
          </Glitch>
        </div>
      ) : t < 3.75 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 760, display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
          <Glitch t={t} at={2.1} d={0.16}>
            <Big t={t} words={[["Então", 2.1], ["presta", 2.2]]} size={150} out={3.6} />
          </Glitch>
          <Big t={t} words={[["atenção!", 2.45]]} size={186} out={3.64} color={RED} />
        </div>
      ) : null}
      <Title t={t} from={3.82} to={6.8} lines={[{ words: [["Suas", 3.82], ["vitórias", 3.9]], cap: 110 }, { words: [["em", 4.44], ["premiações", 4.52]], color: GOLD, cap: 104 }]} />
    </>
  );
};

