// ───────── cena 5: ranking ─────────
// a sua linha sobe degrau por degrau: 6º → 5º → 4º → 3º → 2º → 1º
const STEPS = [38.56, 40.18, 40.95, 41.87, 44.12];
export const R1: React.FC<{ t: number }> = ({ t }) => {
  const A = 34.45, top = 640, rowH = 108, gap = 14;
  let pos = 5;
  for (const s of STEPS) pos -= io(t, s, 0.45);
  const best = io(t, 42.74, 0.5);
  return (
    <>
      <Cam t={t} a={A} b={45.8} z={[1.08, 1.0]} y={[40, -20]}>
        {/* faixa dos melhores (top 3) */}
        <div style={{ position: "absolute", left: 104, width: 872, top: top - 16, height: 3 * (rowH + gap) + 18, borderRadius: 32, border: `4px solid ${GOLD}`, boxSizing: "border-box", opacity: best, transform: `scale(${(0.96 + 0.04 * best).toFixed(3)})`, boxShadow: "0 0 30px rgba(220,184,89,0.3)" }} />
        {[0, 1, 2, 3, 4, 5].map((i) => {
          const me = i === 5;
          // as outras linhas descem uma casa quando a sua passa por elas
          const o = me ? pos : i + Math.min(1, Math.max(0, i + 1 - pos));
          const p = Math.round(o) + 1;
          const e = k(t, A + 0.3 + i * 0.07, 0.45);
          return (
            <div key={i} style={{ position: "absolute", left: 120, width: 840, top: top + o * (rowH + gap), height: rowH, borderRadius: 24, background: me ? "rgba(255,42,63,0.14)" : PANEL, border: `3px solid ${me ? RED : EDGE}`, boxSizing: "border-box", display: "flex", alignItems: "center", gap: 24, padding: "0 30px", opacity: e, transform: `translateX(${((1 - e) * 160).toFixed(1)}px) scale(${(1 + (me ? STEPS.reduce((m, s) => m + bump(t, s, 0.04, 0.35), 0) : 0)).toFixed(3)})`, zIndex: me ? 3 : 1, boxShadow: me ? "0 10px 30px rgba(255,42,63,0.3)" : undefined }}>
              <div style={{ width: 80, fontFamily: SAIRA, fontWeight: 900, fontSize: 50, color: p === 1 ? GOLD : p <= 3 ? WHITE : GRAY }}>#{p}</div>
              <div style={{ width: 62, height: 62, borderRadius: 31, background: me ? RED : "#3A3A44" }} />
              {me ? <div style={{ fontFamily: SAIRA, fontWeight: 800, fontSize: 46, color: WHITE }}>VOCÊ</div> : <Bar w={240 - i * 14} h={20} />}
              <div style={{ flex: 1 }} />
