              ) : (
                <Bar w={90} h={20} c="#2E2E37" />
              )}
            </div>
          );
        })}
        {/* premiações para os primeiros */}
        <div style={{ position: "absolute", left: 0, right: 0, top: 1420, display: "flex", justifyContent: "center", gap: 26 }}>
          {[GOLD, "#C9CDD4", "#8C6A4A"].map((c, i) => (
            <div key={i} style={{ width: 230, height: 190, borderRadius: 28, background: PANEL, border: `4px solid ${c}`, boxSizing: "border-box", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 10, transform: `scale(${pop(t, 44.12 + i * 0.1, 0.45).toFixed(3)})` }}>
              <Ico name="trophy" size={70} color={c} stroke={8} />
              <div style={{ fontFamily: SAIRA, fontWeight: 900, fontSize: 40, color: c }}>{i + 1}º</div>
            </div>
          ))}
        </div>
      </Cam>
      <Title t={t} from={A + 0.1} to={35.75} lines={[{ words: [["E", 34.58], ["não", 34.58], ["para", 34.8]], cap: 110 }, { words: [["por", 34.86], ["aí!", 35.23]], color: RED, cap: 110 }]} />
