import React from "react";
import { AbsoluteFill, OffthreadVideo, Sequence } from "remotion";
import { KR_FPS, asset, k, lin, mix } from "./base";

// RIVAL motion VALORANT v3 — camada de gameplay em tela cheia por baixo das cenas. Os trechos vêm do vídeo que o dono
// mandou (compilação do canal "V de Valorant"), recortados só no centro da tela: sem facecam, nome de Twitch, QR code
// nem a marca do canal. Mudos. Escurecidos de leve para o texto ler; o alto mais escuro onde fica o título.

type Clip = { at: number; end: number; file: string; rate?: number; from?: number };
export const JOGO: Clip[] = [
  { at: 0.0, end: 0.68, file: "tiro" },
  { at: 1.04, end: 2.02, file: "habilidade" },
  { at: 2.44, end: 3.81, file: "agente" },
  { at: 4.5, end: 6.95, file: "lotus" },
  { at: 22.38, end: 26.85, file: "mira", rate: 0.6 },
  { at: 34.45, end: 36.3, file: "tiro" },
  { at: 45.65, end: 47.45, file: "mapa" },
];
export const inGame = (t: number) => JOGO.some((c) => t >= c.at && t < c.end);

export const GameLayer: React.FC<{ t: number }> = ({ t }) => (
  <>
    {JOGO.map((c, i) => {
      if (t < c.at - 0.05 || t >= c.end) return null;
      const z = mix(1.12, 1.0, k(t, c.at, 0.5)) * mix(1, 1.05, lin(t, c.at, c.end));
      // saída do lotus/mira: some enquanto as linhas da cena entram por cima
      const fade = c.at === 34.45 ? 1 - lin(t, 35.9, 36.3) : 1;
      return (
        <AbsoluteFill key={i} style={{ opacity: fade }}>
          <AbsoluteFill style={{ transform: `scale(${z.toFixed(4)})` }}>
            <Sequence from={Math.round(c.at * KR_FPS)} durationInFrames={Math.ceil((c.end - c.at) * KR_FPS) + 2} layout="none">
              <OffthreadVideo src={asset(`jogo/${c.file}.mp4`)} muted playbackRate={c.rate ?? 1} style={{ width: 1080, height: 1920 }} />
            </Sequence>
          </AbsoluteFill>
          <AbsoluteFill style={{ background: "rgba(5,5,8,0.38)" }} />
          <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(5,5,8,0.72) 0%, rgba(5,5,8,0.35) 30%, rgba(5,5,8,0) 50%, rgba(5,5,8,0) 80%, rgba(5,5,8,0.45) 100%)" }} />
        </AbsoluteFill>
      );
    })}
  </>
);

import React from "react";
import { Easing, Img, interpolate, staticFile } from "remotion";
import { BG, EDGE, RED } from "./base";

// v6 (VALORANT): telas reais do site (sandbox, Modo Amostra) no lugar das telas desenhadas, só em quatro trechos.
// O título, o tema claro/escuro, a voz, a música e o ritmo da v5 não mudam: a janela cobre apenas a área onde ficava
// o desenho (x 60–1020, y 605–1535). Coordenadas das telas no espaço 800 x 1422 do print de celular.
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const GOLD = "#DCB859", TEAL = "#009982";
const WX = 120, WY = 625, WW = 840, WH = 900, IW = 800, IH = 1422;
type KF = [number, number, number, number]; // tempo, centro x, centro y, zoom
type Mark = { x: number; y: number; w: number; h: number; at: number; out?: number; c: string };
type Shot = { src: string; at: number; kf: KF[]; enter?: "up" | "right" | "zoom"; marks?: Mark[] };
type Bloco = { a: number; b: number; shots: Shot[] };

const cam = (t: number, kf: KF[]) => {
  let v = [kf[0][1], kf[0][2], kf[0][3]];
  for (let i = 0; i < kf.length - 1; i++) {
    const [p, q] = [kf[i], kf[i + 1]];
    if (t >= p[0]) { const u = io(t, p[0], q[0]); v = [p[1] + (q[1] - p[1]) * u, p[2] + (q[2] - p[2]) * u, p[3] + (q[3] - p[3]) * u]; }
  }
  const [cx, cy, s] = v; const hw = WW / 2 / s, hh = WH / 2 / s;
  return { s, cx: hw >= IW / 2 ? IW / 2 : Math.min(IW - hw, Math.max(hw, cx)), cy: Math.min(IH - hh, Math.max(hh, cy)) };
};

const BLOCOS: Bloco[] = [
  // "uma nova plataforma competitiva onde suas partidas de Valorant podem valer dinheiro"
  { a: 10.55, b: 14.7, shots: [
    { src: "hub-1-topo", at: 10.55, kf: [[10.55, 400, 430, 1.05], [11.3, 400, 430, 1.05], [12.4, 400, 780, 1.05]] },
    { src: "hub-3-fila-salas", at: 12.65, enter: "up", kf: [[12.65, 400, 430, 1.05], [13.3, 400, 330, 1.2]], marks: [{ x: 406, y: 224, w: 324, h: 100, at: 13.4, c: GOLD }] },
  ] },
  // "Entre nos HUBs, dispute partidas cinco contra cinco e concorra a premiações em dinheiro"
  { a: 15.35, b: 20.35, shots: [
    { src: "sala-1-topo", at: 15.35, kf: [[15.35, 400, 430, 1.05], [16.1, 400, 430, 1.05], [16.7, 380, 520, 1.2]], marks: [{ x: 60, y: 432, w: 680, h: 120, at: 16.6, c: RED }] },
    { src: "sala-2-vagas", at: 17.45, enter: "up", kf: [[17.45, 400, 430, 1.05], [18.6, 400, 900, 1.05]] },
    { src: "hub-3-fila-salas", at: 18.7, enter: "right", kf: [[18.7, 400, 990, 1.05], [19.3, 400, 1045, 1.2]], marks: [{ x: 406, y: 1158, w: 328, h: 96, at: 19.3, c: GOLD }] },
  ] },
  // "Participe de campeonatos, desafie outras equipes e dispute premiações em dinheiro com seu time"
  { a: 28.45, b: 34.2, shots: [
    { src: "torneios-1-lista", at: 28.45, kf: [[28.45, 400, 430, 1.05], [29.7, 400, 760, 1.1]] },
    { src: "torneio-3-chave", at: 29.85, enter: "right", kf: [[29.85, 400, 430, 1.05], [31.3, 400, 900, 1.05]] },
    { src: "torneio-1-tier1", at: 31.4, enter: "up", kf: [[31.4, 400, 760, 1.05], [32.1, 360, 1000, 1.3]], marks: [{ x: 56, y: 1056, w: 300, h: 100, at: 32.1, c: GOLD }] },
  ] },
  // "Cada partida pode contar para sua evolução no ranking"
  { a: 36.3, b: 39.95, shots: [
    { src: "tabela-2-classificacao", at: 36.3, kf: [[36.3, 400, 430, 1.05], [38.2, 400, 700, 1.05], [39.0, 420, 560, 1.2]], marks: [{ x: 620, y: 246, w: 112, h: 660, at: 38.4, c: TEAL }] },
  ] },
];

export const SiteLayer: React.FC<{ t: number }> = ({ t }) => {
  const bl = BLOCOS.find((x) => t >= x.a - 0.02 && t < x.b);
  if (!bl) return null;
  const en = k(t, bl.a, 0.5), ex = lin(t, bl.b - 0.16, bl.b);
  return (
    <>
      {/* cobre o desenho antigo com a cor de fundo do tema */}
      <div style={{ position: "absolute", left: 60, top: 605, width: 960, height: 930, background: BG, opacity: Math.min(1, lin(t, bl.a, bl.a + 0.12)) * (1 - ex) }} />
      <div style={{ position: "absolute", left: WX, top: WY, width: WW, height: WH, borderRadius: 36, overflow: "hidden", background: "#050506", border: `2px solid ${EDGE}`, boxShadow: "0 30px 80px rgba(0,0,0,0.38)", transform: `translateY(${((1 - en) * 130).toFixed(1)}px) scale(${(0.93 + 0.07 * en + 0.03 * ex).toFixed(4)})`, opacity: Math.min(1, en * 1.8) * (1 - ex) }}>
        {bl.shots.map((sh, i) => {
          const fim = bl.shots[i + 1] ? bl.shots[i + 1].at + 0.42 : bl.b + 0.2;
          if ((i > 0 && t < sh.at - 0.02) || t > fim) return null;
          const c = cam(t, sh.kf);
          const e = i === 0 ? 1 : k(t, sh.at, 0.4);
          const tr = sh.enter === "right" ? `translateX(${((1 - e) * WW).toFixed(1)}px)` : sh.enter === "zoom" ? `scale(${(1.18 - 0.18 * e).toFixed(4)})` : `translateY(${((1 - e) * WH).toFixed(1)}px)`;
          return (
            <div key={i} style={{ position: "absolute", inset: 0, overflow: "hidden", background: "#050506", transform: tr }}>
              <div style={{ position: "absolute", left: 0, top: 0, width: IW, height: IH, transformOrigin: "0 0", transform: `translate(${(WW / 2 - c.cx * c.s).toFixed(2)}px, ${(WH / 2 - c.cy * c.s).toFixed(2)}px) scale(${c.s.toFixed(4)})` }}>
                <Img src={staticFile(`kaio-rivalx/site/${sh.src}.jpg`)} style={{ width: IW, height: IH, display: "block" }} />
                {sh.marks?.map((m, j) => {
                  if (t < m.at) return null;
                  const p = k(t, m.at, 0.35);
                  return <div key={j} style={{ position: "absolute", left: m.x, top: m.y, width: m.w, height: m.h, border: `4px solid ${m.c}`, borderRadius: 12, background: `${m.c}1F`, boxShadow: `0 0 26px ${m.c}99`, opacity: p, transform: `scale(${(1.14 - 0.14 * p).toFixed(4)})` }} />;
                })}
              </div>
            </div>
          );
        })}
      </div>
    </>
  );
};

